package main

import (
	"fmt"
	"sync"
	"time"

	"github.com/bluele/gcache"
)

func main() {
	// Create a small cache that will trigger eviction
	cache := gcache.New(2).Build()

	var wg sync.WaitGroup

	// Start multiple goroutines that will cause evictions
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for j := 0; j < 100; j++ {
				key := fmt.Sprintf("key-%d-%d", id, j)
				cache.Set(key, fmt.Sprintf("value-%d-%d", id, j))
				// Try to get the value back
				if _, err := cache.Get(key); err != nil {
					fmt.Printf("Error getting key %s: %v\n", key, err)
				}
				time.Sleep(time.Microsecond) // Small delay to increase chance of race
			}
		}(i)
	}

	// Also test the Has method concurrently
	for i := 0; i < 5; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for j := 0; j < 100; j++ {
				key := fmt.Sprintf("check-key-%d-%d", id, j)
				cache.Has(key)
				time.Sleep(time.Microsecond) // Small delay to increase chance of race
			}
		}(i)
	}

	wg.Wait()
	fmt.Println("All goroutines finished successfully!")
}
EOF
```

